WITH v(id,title,descr,task,ans) AS (VALUES
('dr_sanitary','Помощник мастера','Только начинаете: подаёте инструменты, готовите рабочее место, встречаете клиенток.','Клиентка спрашивает вас, почему мастер задерживается уже на 15 минут. Что вы ей скажете?','«Простите за ожидание. Мастер заканчивает сложную процедуру, освободится примерно через 10 минут. Предложить вам чай или кофе?»'),
('dr_junior','Мастер','Работаете с клиентками в кресле, отвечаете за результат и впечатление.','Клиентка показывает фото из интернета и просит такой же результат, но её волосы этого не позволяют. Ответьте ей.','«Мне очень нравится этот образ. Точь-в-точь не получится, но я сделаю близкий вариант и сохраню здоровье волос. Давайте покажу, как это будет выглядеть».'),
('dr_driver','Топ-мастер','Опытный мастер, к вам записываются заранее, коллеги советуются с вами.','Молодой мастер просит вас взять его сложную клиентку, потому что боится не справиться. Что вы ответите?','«Давай вместе: я подскажу план, а сделаешь ты, я буду рядом. Так ты наберёшь опыт, а клиентка получит результат».'),
('dr_admin','Администратор','Встречаете клиенток, ведёте запись, решаете спорные ситуации.','Клиентка пришла без записи и требует принять её прямо сейчас, все мастера заняты. Ответьте.','«Понимаю, что вам срочно. Сейчас все мастера заняты, ближайшее окно — в 16:30. Могу записать вас и сообщить, если освободится раньше».'),
('dr_lab_nurse','Старший администратор','Отвечаете за смену администраторов и сложных гостей.','Новая администраторка ошиблась в записи, и две клиентки пришли на одно время. Как вы поговорите с ней после смены?','«Давай разберём, как так вышло, без поиска виноватых. Покажу, как проверять запись перед подтверждением».'),
('dr_checkup_doc','SMM-специалист','Ведёте соцсети салона, отвечаете на комментарии и сообщения.','Под постом салона клиентка оставила негативный комментарий о плохом окрашивании. Напишите ответ.','«Нам очень жаль, что результат вас расстроил. Напишите нам в личные сообщения — разберёмся и предложим бесплатную коррекцию».'),
('dr_therapist','Маркетолог','Придумываете акции и привлекаете новых клиенток.','Мастера недовольны новой акцией: «Скидки — это работа бесплатно». Как вы объясните им её смысл?','«Акция приводит новых клиенток, а зарабатываем мы на их возвращении. В прошлый раз 40% вернулись по полной цене».'),
('dr_accountant','Управляющая','Отвечаете за работу салона: команду, график, сервис.','Два мастера поссорились из-за кресла у окна и не разговаривают. Что вы скажете им на встрече?','«Мне важно, чтобы вам обеим было комфортно. Давайте договоримся о графике: чётные дни у окна одна, нечётные — другая».'),
('dr_head','Владелец салона','Принимаете ключевые решения, отвечаете за доход и атмосферу.','Ваш лучший мастер говорит, что уходит в другой салон за большим процентом. Как вы начнёте разговор?','«Спасибо, что сказала честно. Ты для нас очень ценна. Давай обсудим, что для тебя важно, кроме процента, и что я могу предложить».'),
('dr_owner','Владелец сети студий','Управляете несколькими студиями и управляющими.','В одной из студий упали отзывы. Управляющая считает, что виноваты мастера. Как вы проведёте разговор с ней?','«Давай посмотрим на цифры вместе. Мне важно понять причину, а не найти виноватых. Какой план ты предлагаешь?»')
), r AS (
  INSERT INTO public.daily_roles(id,title,description,is_active) SELECT id,title,descr,true FROM v
  ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, description=EXCLUDED.description, is_active=true RETURNING id
), c AS (
  INSERT INTO public.daily_role_context(role_id,who_you_are,where_you_are,what_to_remember)
  SELECT id, 'Вы — '||title||'. '||descr, 'Салон красоты', 'Сохраняйте спокойствие и уважение к собеседнику.' FROM v RETURNING 1
)
INSERT INTO public.daily_tasks(id,role_id,type,question,criteria,model_answer,level)
SELECT 'dt_'||v.id, v.id, 'open', task, '["Вежливость и тон","Понимание чувств собеседника","Ясное решение или предложение","Сохранение границ и правил салона"]'::jsonb, ans, 1
FROM v JOIN r ON r.id=v.id ON CONFLICT (id) DO NOTHING;